// @pit: {"label": "Check gh/npm signatures and why execFile replaced typed calls"}
async ({ functions: { getSaved } }, p: { js: string }) => {
  const names = ["gh.prCreate", "gh.prMerge", "gh.prView", "gh.prList", "gh.runView", "gh.runList", "npm.install", "git.push", "git.diff", "gh.issueComment", "shell.execFile"];
  const sigs = await Promise.allSettled(names.map((n) => getSaved(n)));
  return sigs.map((r, i) => names[i] + " :: " + (r.status === "fulfilled" ? (r.value as any).signature : String(r.reason)));
}

// @pit: {"label": "Show contexts of date, gh pr view/merge/create, and npm ci via execFile"}
async ({ shell: { exec } }, p: { js: string }) => {
  const s = await exec(`cat > /tmp/ctx.mjs <<'EOF'\n${p.js}\nEOF\nnode /tmp/ctx.mjs`, { timeoutMs: 28000 });
  return s.stdout.slice(0, 30000) + s.stderr.slice(0, 3000);
}

